static inline int fzn_gather_wire_fzn_gather_lines_lines_fits(situ_view_t view)
{
	const uint32_t total = fzn_gather_wire_fzn_gather_lines_lines_count(view);
	uint32_t at = 21u;
	uint32_t n  = 0u;

	while (n < total) {
		situ_view_t element;
		uint32_t    size;

		if (at >= view.limit) {
			return 0;
		}
		if (situ_view_sub(view, at, situ_remaining_u32(view.limit, at), &element)
				!= SITU_OK) {
			return 0;
		}
		size = fzn_gather_wire_fzn_gather_line_extent(element);
		if (size == 0u) {
			return 0;
		}
		if (size > situ_remaining_u32(view.limit, at)) {
			return 0;
		}
		at = at + size;
		n  = n + 1u;
	}
	return 1;
}

